INSERT INTO [ConsultasSQL_Catalogo] ([ConsultaID], [PublicUUID], [CodigoConsulta], [NombreConsulta], [Descripcion], [Modulo], [TipoConsulta], [SistemaTipoID], [ConsultaSQL], [EsSistema], [EsPersonalizada], [EsSincronizable], [PermiteEjecucionManual], [SoloLectura], [RequiereAutorizacion], [Activo], [Version], [ConfigOrigen], [FechaCreacion], [UsuarioCreacionID], [FechaModificacion], [UsuarioModificacionID]) VALUES (1, '49a849a8-0c73-4e46-b859-45e8191414a6', N'SR_VENTAS_DIA', N'Ventas del Día', N'Total de ventas, cheques y comensales del día seleccionado', N'Ventas', N'CONSULTA', 1, N'SELECT      COUNT(DISTINCT cheques.folio) as Cheques,     ISNULL(SUM(cheques.total), 0) as Venta_Total,     ISNULL(SUM(cheques.nopersonas), 0) as PAX,     ISNULL(AVG(cheques.total), 0) as Cheque_Promedio,     ISNULL(AVG(CAST(cheques.nopersonas as float)), 0) as PAX_Promedio FROM cheques INNER JOIN turnos ON turnos.idturno = cheques.idturno WHERE CONVERT(date, turnos.apertura) = ''{fecha}''   AND cheques.cancelado = 0', 1, 0, 0, 1, 1, 0, 1, 1, N'LEGACY_PYTHON', N'2026-05-15T04:08:17.796666', N'SISTEMA', NULL, NULL);
INSERT INTO [ConsultasSQL_Catalogo] ([ConsultaID], [PublicUUID], [CodigoConsulta], [NombreConsulta], [Descripcion], [Modulo], [TipoConsulta], [SistemaTipoID], [ConsultaSQL], [EsSistema], [EsPersonalizada], [EsSincronizable], [PermiteEjecucionManual], [SoloLectura], [RequiereAutorizacion], [Activo], [Version], [ConfigOrigen], [FechaCreacion], [UsuarioCreacionID], [FechaModificacion], [UsuarioModificacionID]) VALUES (2, '0db2b39f-d907-4853-9f53-a227c7a2ac40', N'SR_VENTAS_PERIODO', N'Ventas por Período', N'Total de ventas entre dos fechas', N'Ventas', N'CONSULTA', 1, N'SELECT      COUNT(DISTINCT cheques.folio) as Cheques,     ISNULL(SUM(cheques.total), 0) as Venta_Total,     ISNULL(SUM(cheques.nopersonas), 0) as PAX,     ISNULL(AVG(cheques.total), 0) as Cheque_Promedio FROM cheques INNER JOIN turnos ON turnos.idturno = cheques.idturno WHERE turnos.apertura >= ''{fecha_ini} 00:00:00''   AND turnos.apertura <= ''{fecha_fin} 23:59:59''   AND cheques.cancelado = 0', 1, 0, 0, 1, 1, 0, 1, 1, N'LEGACY_PYTHON', N'2026-05-15T04:08:17.830000', N'SISTEMA', NULL, NULL);
INSERT INTO [ConsultasSQL_Catalogo] ([ConsultaID], [PublicUUID], [CodigoConsulta], [NombreConsulta], [Descripcion], [Modulo], [TipoConsulta], [SistemaTipoID], [ConsultaSQL], [EsSistema], [EsPersonalizada], [EsSincronizable], [PermiteEjecucionManual], [SoloLectura], [RequiereAutorizacion], [Activo], [Version], [ConfigOrigen], [FechaCreacion], [UsuarioCreacionID], [FechaModificacion], [UsuarioModificacionID]) VALUES (3, '37f981fd-119d-4b42-b692-b351fcef2861', N'SR_VENTAS_POR_DIA', N'Ventas Desglosadas por Día', N'Ventas día a día en un período', N'Ventas', N'CONSULTA', 1, N'SELECT      CONVERT(date, turnos.apertura) as Fecha,     COUNT(DISTINCT cheques.folio) as Cheques,     ISNULL(SUM(cheques.total), 0) as Venta,     ISNULL(SUM(cheques.nopersonas), 0) as PAX FROM cheques INNER JOIN turnos ON turnos.idturno = cheques.idturno WHERE turnos.apertura >= ''{fecha_ini} 00:00:00''   AND turnos.apertura <= ''{fecha_fin} 23:59:59''   AND cheques.cancelado = 0 GROUP BY CONVERT(date, turnos.apertura) ORDER BY CONVERT(date, turnos.apertura)', 1, 0, 0, 1, 1, 0, 1, 1, N'LEGACY_PYTHON', N'2026-05-15T04:08:17.926666', N'SISTEMA', NULL, NULL);
INSERT INTO [ConsultasSQL_Catalogo] ([ConsultaID], [PublicUUID], [CodigoConsulta], [NombreConsulta], [Descripcion], [Modulo], [TipoConsulta], [SistemaTipoID], [ConsultaSQL], [EsSistema], [EsPersonalizada], [EsSincronizable], [PermiteEjecucionManual], [SoloLectura], [RequiereAutorizacion], [Activo], [Version], [ConfigOrigen], [FechaCreacion], [UsuarioCreacionID], [FechaModificacion], [UsuarioModificacionID]) VALUES (4, '49d582a0-73f0-4d8c-8d6d-6298e752c846', N'SR_VENTAS_POR_HORA', N'Ventas por Hora', N'Distribución de ventas por hora del día', N'Ventas', N'CONSULTA', 1, N'SELECT      DATEPART(HOUR, cheques.fecha) as Hora,     COUNT(DISTINCT cheques.folio) as Cheques,     ISNULL(SUM(cheques.total), 0) as Venta,     ISNULL(SUM(cheques.nopersonas), 0) as PAX FROM cheques INNER JOIN turnos ON turnos.idturno = cheques.idturno WHERE turnos.apertura >= ''{fecha_ini} 00:00:00''   AND turnos.apertura <= ''{fecha_fin} 23:59:59''   AND cheques.cancelado = 0 GROUP BY DATEPART(HOUR, cheques.fecha) ORDER BY DATEPART(HOUR, cheques.fecha)', 1, 0, 0, 1, 1, 0, 1, 1, N'LEGACY_PYTHON', N'2026-05-15T04:08:17.953333', N'SISTEMA', NULL, NULL);
INSERT INTO [ConsultasSQL_Catalogo] ([ConsultaID], [PublicUUID], [CodigoConsulta], [NombreConsulta], [Descripcion], [Modulo], [TipoConsulta], [SistemaTipoID], [ConsultaSQL], [EsSistema], [EsPersonalizada], [EsSincronizable], [PermiteEjecucionManual], [SoloLectura], [RequiereAutorizacion], [Activo], [Version], [ConfigOrigen], [FechaCreacion], [UsuarioCreacionID], [FechaModificacion], [UsuarioModificacionID]) VALUES (5, 'd3968875-e393-47fb-830d-43507b8d9a9e', N'SR_VENTAS_POR_MESERO', N'Ventas por Mesero', N'Ranking de ventas por mesero/vendedor', N'Ventas', N'CONSULTA', 1, N'SELECT      ISNULL(m.nombre, ''Sin asignar'') as Mesero,     COUNT(DISTINCT cheques.folio) as Cheques,     ISNULL(SUM(cheques.total), 0) as Venta,     ISNULL(SUM(cheques.nopersonas), 0) as PAX,     ISNULL(AVG(cheques.total), 0) as Cheque_Promedio FROM cheques LEFT JOIN meseros m ON m.idmesero = cheques.idmesero INNER JOIN turnos ON turnos.idturno = cheques.idturno WHERE turnos.apertura >= ''{fecha_ini} 00:00:00''   AND turnos.apertura <= ''{fecha_fin} 23:59:59''   AND cheques.cancelado = 0 GROUP BY m.nombre ORDER BY SUM(cheques.total) DESC', 1, 0, 0, 1, 1, 0, 1, 1, N'LEGACY_PYTHON', N'2026-05-15T04:08:17.990000', N'SISTEMA', NULL, NULL);
INSERT INTO [ConsultasSQL_Catalogo] ([ConsultaID], [PublicUUID], [CodigoConsulta], [NombreConsulta], [Descripcion], [Modulo], [TipoConsulta], [SistemaTipoID], [ConsultaSQL], [EsSistema], [EsPersonalizada], [EsSincronizable], [PermiteEjecucionManual], [SoloLectura], [RequiereAutorizacion], [Activo], [Version], [ConfigOrigen], [FechaCreacion], [UsuarioCreacionID], [FechaModificacion], [UsuarioModificacionID]) VALUES (6, 'be3324bb-b1aa-450d-bcaf-9357560b0324', N'SR_VENTAS_POR_PRODUCTO', N'Ventas por Producto', N'Top productos más vendidos', N'Ventas', N'CONSULTA', 1, N'SELECT TOP 50     p.idproducto as Codigo,     p.descripcion as Producto,     SUM(cd.cantidad) as Cantidad,     SUM(cd.cantidad * cd.precio) as Venta FROM cheqdet cd INNER JOIN cheques ON cheques.folio = cd.foliodet INNER JOIN productos p ON p.idproducto = cd.idproducto INNER JOIN turnos ON turnos.idturno = cheques.idturno WHERE turnos.apertura >= ''{fecha_ini} 00:00:00''   AND turnos.apertura <= ''{fecha_fin} 23:59:59''   AND cheques.cancelado = 0 GROUP BY p.idproducto, p.descripcion ORDER BY SUM(cd.cantidad * cd.precio) DESC', 1, 0, 0, 1, 1, 0, 1, 1, N'LEGACY_PYTHON', N'2026-05-15T04:08:17.996666', N'SISTEMA', NULL, NULL);
INSERT INTO [ConsultasSQL_Catalogo] ([ConsultaID], [PublicUUID], [CodigoConsulta], [NombreConsulta], [Descripcion], [Modulo], [TipoConsulta], [SistemaTipoID], [ConsultaSQL], [EsSistema], [EsPersonalizada], [EsSincronizable], [PermiteEjecucionManual], [SoloLectura], [RequiereAutorizacion], [Activo], [Version], [ConfigOrigen], [FechaCreacion], [UsuarioCreacionID], [FechaModificacion], [UsuarioModificacionID]) VALUES (7, 'c543e8e4-c517-4926-9df5-0a0ece78413f', N'SR_CORTESIAS', N'Cortesías y Descuentos', N'Detalle de cortesías aplicadas', N'Ventas', N'CONSULTA', 1, N'SELECT      CONVERT(date, turnos.apertura) as Fecha,     cheques.folio as Folio,     ISNULL(m.nombre, ''N/A'') as Mesero,     cheques.subtotal as Subtotal,     cheques.descuento as Descuento,     cheques.total as Total,     cheques.razondescuento as Razon FROM cheques LEFT JOIN meseros m ON m.idmesero = cheques.idmesero INNER JOIN turnos ON turnos.idturno = cheques.idturno WHERE turnos.apertura >= ''{fecha_ini} 00:00:00''   AND turnos.apertura <= ''{fecha_fin} 23:59:59''   AND cheques.descuento > 0 ORDER BY turnos.apertura DESC', 1, 0, 0, 1, 1, 0, 1, 1, N'LEGACY_PYTHON', N'2026-05-15T04:08:18.023333', N'SISTEMA', NULL, NULL);
INSERT INTO [ConsultasSQL_Catalogo] ([ConsultaID], [PublicUUID], [CodigoConsulta], [NombreConsulta], [Descripcion], [Modulo], [TipoConsulta], [SistemaTipoID], [ConsultaSQL], [EsSistema], [EsPersonalizada], [EsSincronizable], [PermiteEjecucionManual], [SoloLectura], [RequiereAutorizacion], [Activo], [Version], [ConfigOrigen], [FechaCreacion], [UsuarioCreacionID], [FechaModificacion], [UsuarioModificacionID]) VALUES (8, '1197b485-ad73-4f4b-a177-763996a9337e', N'SR_CANCELACIONES', N'Cancelaciones', N'Cheques cancelados en el período', N'Ventas', N'CONSULTA', 1, N'SELECT      CONVERT(date, turnos.apertura) as Fecha,     cheques.folio as Folio,     ISNULL(m.nombre, ''N/A'') as Mesero,     cheques.total as Monto,     cheques.razoncancelado as Razon FROM cheques LEFT JOIN meseros m ON m.idmesero = cheques.idmesero INNER JOIN turnos ON turnos.idturno = cheques.idturno WHERE turnos.apertura >= ''{fecha_ini} 00:00:00''   AND turnos.apertura <= ''{fecha_fin} 23:59:59''   AND cheques.cancelado = 1 ORDER BY turnos.apertura DESC', 1, 0, 0, 1, 1, 0, 1, 1, N'LEGACY_PYTHON', N'2026-05-15T04:08:18.033333', N'SISTEMA', NULL, NULL);
INSERT INTO [ConsultasSQL_Catalogo] ([ConsultaID], [PublicUUID], [CodigoConsulta], [NombreConsulta], [Descripcion], [Modulo], [TipoConsulta], [SistemaTipoID], [ConsultaSQL], [EsSistema], [EsPersonalizada], [EsSincronizable], [PermiteEjecucionManual], [SoloLectura], [RequiereAutorizacion], [Activo], [Version], [ConfigOrigen], [FechaCreacion], [UsuarioCreacionID], [FechaModificacion], [UsuarioModificacionID]) VALUES (9, '4bf9c8a2-7efb-4faa-8127-8392cde100c2', N'SR_COMPRAS_PERIODO', N'Compras por Período', N'Total de compras entre dos fechas', N'Compras', N'CONSULTA', 1, N'SELECT      COUNT(DISTINCT c.idcompra) as Facturas,     ISNULL(SUM(c.total), 0) as Compra_Total FROM compras c WHERE c.fechaaplicacion >= ''{fecha_ini}''   AND c.fechaaplicacion <= ''{fecha_fin} 23:59:59''   AND c.cancelado = 0', 1, 0, 0, 1, 1, 0, 1, 1, N'LEGACY_PYTHON', N'2026-05-15T04:08:18.033333', N'SISTEMA', NULL, NULL);
INSERT INTO [ConsultasSQL_Catalogo] ([ConsultaID], [PublicUUID], [CodigoConsulta], [NombreConsulta], [Descripcion], [Modulo], [TipoConsulta], [SistemaTipoID], [ConsultaSQL], [EsSistema], [EsPersonalizada], [EsSincronizable], [PermiteEjecucionManual], [SoloLectura], [RequiereAutorizacion], [Activo], [Version], [ConfigOrigen], [FechaCreacion], [UsuarioCreacionID], [FechaModificacion], [UsuarioModificacionID]) VALUES (10, '964c20f7-84c7-4ec7-a9c5-ca8218baa445', N'SR_COMPRAS_POR_PROVEEDOR', N'Compras por Proveedor', N'Desglose de compras por proveedor', N'Compras', N'CONSULTA', 1, N'SELECT      ISNULL(p.nombre, ''Sin proveedor'') as Proveedor,     COUNT(DISTINCT c.idcompra) as Facturas,     ISNULL(SUM(c.total), 0) as Compra_Total FROM compras c LEFT JOIN proveedores p ON p.idproveedor = c.idproveedor WHERE c.fechaaplicacion >= ''{fecha_ini}''   AND c.fechaaplicacion <= ''{fecha_fin} 23:59:59''   AND c.cancelado = 0 GROUP BY p.nombre ORDER BY SUM(c.total) DESC', 1, 0, 0, 1, 1, 0, 1, 1, N'LEGACY_PYTHON', N'2026-05-15T04:08:18.043333', N'SISTEMA', NULL, NULL);
INSERT INTO [ConsultasSQL_Catalogo] ([ConsultaID], [PublicUUID], [CodigoConsulta], [NombreConsulta], [Descripcion], [Modulo], [TipoConsulta], [SistemaTipoID], [ConsultaSQL], [EsSistema], [EsPersonalizada], [EsSincronizable], [PermiteEjecucionManual], [SoloLectura], [RequiereAutorizacion], [Activo], [Version], [ConfigOrigen], [FechaCreacion], [UsuarioCreacionID], [FechaModificacion], [UsuarioModificacionID]) VALUES (11, '94bf3021-eefa-4834-97c0-eb4937531f67', N'SR_COMPRAS_POR_PRODUCTO', N'Compras por Producto', N'Detalle de productos comprados', N'Compras', N'CONSULTA', 1, N'SELECT TOP 50     i.idinsumo as Codigo,     i.descripcion as Producto,     SUM(cm.cantidad) as Cantidad,     AVG(cm.costo) as Costo_Promedio,     SUM(cm.cantidad * cm.costo) as Compra_Total FROM comprasmovtos cm INNER JOIN compras c ON c.idcompra = cm.idcompra INNER JOIN insumos i ON i.idinsumo = cm.idinsumo WHERE c.fechaaplicacion >= ''{fecha_ini}''   AND c.fechaaplicacion <= ''{fecha_fin} 23:59:59''   AND c.cancelado = 0 GROUP BY i.idinsumo, i.descripcion ORDER BY SUM(cm.cantidad * cm.costo) DESC', 1, 0, 0, 1, 1, 0, 1, 1, N'LEGACY_PYTHON', N'2026-05-15T04:08:18.043333', N'SISTEMA', NULL, NULL);
INSERT INTO [ConsultasSQL_Catalogo] ([ConsultaID], [PublicUUID], [CodigoConsulta], [NombreConsulta], [Descripcion], [Modulo], [TipoConsulta], [SistemaTipoID], [ConsultaSQL], [EsSistema], [EsPersonalizada], [EsSincronizable], [PermiteEjecucionManual], [SoloLectura], [RequiereAutorizacion], [Activo], [Version], [ConfigOrigen], [FechaCreacion], [UsuarioCreacionID], [FechaModificacion], [UsuarioModificacionID]) VALUES (12, 'fd65c069-cf5a-4272-9ad8-0166e418917f', N'SR_INVENTARIO_ACTUAL', N'Inventario Actual', N'Existencias actuales por almacén', N'Inventarios', N'CONSULTA', 1, N'SELECT      i.idinsumo as Codigo,     i.descripcion as Producto,     ISNULL(e.existencia, 0) as Existencia,     i.unidadcompra as Unidad,     ISNULL(i.costo, 0) as Costo,     ISNULL(e.existencia * i.costo, 0) as Valor FROM insumos i LEFT JOIN existenciasalmacen e ON e.idinsumo = i.idinsumo LEFT JOIN almacen a ON a.idalmacen = e.idalmacen WHERE a.nombre LIKE ''%{almacen}%''   AND ISNULL(e.existencia, 0) > 0 ORDER BY i.descripcion', 1, 0, 0, 1, 1, 0, 1, 1, N'LEGACY_PYTHON', N'2026-05-15T04:08:18.043333', N'SISTEMA', NULL, NULL);
INSERT INTO [ConsultasSQL_Catalogo] ([ConsultaID], [PublicUUID], [CodigoConsulta], [NombreConsulta], [Descripcion], [Modulo], [TipoConsulta], [SistemaTipoID], [ConsultaSQL], [EsSistema], [EsPersonalizada], [EsSincronizable], [PermiteEjecucionManual], [SoloLectura], [RequiereAutorizacion], [Activo], [Version], [ConfigOrigen], [FechaCreacion], [UsuarioCreacionID], [FechaModificacion], [UsuarioModificacionID]) VALUES (13, '65b57999-d045-4428-9695-ff7ff4fe18a4', N'SR_FORMAS_PAGO', N'Formas de Pago', N'Desglose por forma de pago', N'Pagos', N'CONSULTA', 1, N'SELECT      ISNULL(fp.descripcion, ''Efectivo'') as Forma_Pago,     COUNT(*) as Operaciones,     ISNULL(SUM(cp.importe), 0) as Monto FROM chequespagos cp INNER JOIN cheques c ON c.folio = cp.folio INNER JOIN turnos t ON t.idturno = c.idturno LEFT JOIN formaspago fp ON fp.idformapago = cp.idformapago WHERE t.apertura >= ''{fecha_ini} 00:00:00''   AND t.apertura <= ''{fecha_fin} 23:59:59''   AND c.cancelado = 0 GROUP BY fp.descripcion ORDER BY SUM(cp.importe) DESC', 1, 0, 0, 1, 1, 0, 1, 1, N'LEGACY_PYTHON', N'2026-05-15T04:08:18.046666', N'SISTEMA', NULL, NULL);
INSERT INTO [ConsultasSQL_Catalogo] ([ConsultaID], [PublicUUID], [CodigoConsulta], [NombreConsulta], [Descripcion], [Modulo], [TipoConsulta], [SistemaTipoID], [ConsultaSQL], [EsSistema], [EsPersonalizada], [EsSincronizable], [PermiteEjecucionManual], [SoloLectura], [RequiereAutorizacion], [Activo], [Version], [ConfigOrigen], [FechaCreacion], [UsuarioCreacionID], [FechaModificacion], [UsuarioModificacionID]) VALUES (14, 'ed735fc3-90f1-452b-ae58-6b10325fe32d', N'SR_PROPINAS', N'Propinas', N'Total de propinas por mesero', N'Pagos', N'CONSULTA', 1, N'SELECT      ISNULL(m.nombre, ''Sin asignar'') as Mesero,     COUNT(DISTINCT c.folio) as Cheques,     ISNULL(SUM(c.propina), 0) as Propinas,     ISNULL(SUM(c.total), 0) as Ventas FROM cheques c LEFT JOIN meseros m ON m.idmesero = c.idmesero INNER JOIN turnos t ON t.idturno = c.idturno WHERE t.apertura >= ''{fecha_ini} 00:00:00''   AND t.apertura <= ''{fecha_fin} 23:59:59''   AND c.cancelado = 0   AND c.propina > 0 GROUP BY m.nombre ORDER BY SUM(c.propina) DESC', 1, 0, 0, 1, 1, 0, 1, 1, N'LEGACY_PYTHON', N'2026-05-15T04:08:18.046666', N'SISTEMA', NULL, NULL);
INSERT INTO [ConsultasSQL_Catalogo] ([ConsultaID], [PublicUUID], [CodigoConsulta], [NombreConsulta], [Descripcion], [Modulo], [TipoConsulta], [SistemaTipoID], [ConsultaSQL], [EsSistema], [EsPersonalizada], [EsSincronizable], [PermiteEjecucionManual], [SoloLectura], [RequiereAutorizacion], [Activo], [Version], [ConfigOrigen], [FechaCreacion], [UsuarioCreacionID], [FechaModificacion], [UsuarioModificacionID]) VALUES (15, 'cfb53729-aac5-4b35-860c-524bd2b50171', N'MPRO_VENTAS_PERIODO', N'Ventas por Período', N'Total de ventas MPRO entre dos fechas', N'Ventas', N'CONSULTA', 2, N'SELECT      COUNT(DISTINCT Vn_Folio) as Tickets,     ISNULL(SUM(Vn_Importe), 0) as Venta_Total FROM Venta WHERE Vn_Fecha >= ''{fecha_ini}''    AND Vn_Fecha <= ''{fecha_fin} 23:59:59''   AND ISNULL(Es_Cve_Estado, '''') <> ''CA''', 1, 0, 0, 1, 1, 0, 1, 1, N'LEGACY_PYTHON', N'2026-05-15T04:08:18.046666', N'SISTEMA', NULL, NULL);
INSERT INTO [ConsultasSQL_Catalogo] ([ConsultaID], [PublicUUID], [CodigoConsulta], [NombreConsulta], [Descripcion], [Modulo], [TipoConsulta], [SistemaTipoID], [ConsultaSQL], [EsSistema], [EsPersonalizada], [EsSincronizable], [PermiteEjecucionManual], [SoloLectura], [RequiereAutorizacion], [Activo], [Version], [ConfigOrigen], [FechaCreacion], [UsuarioCreacionID], [FechaModificacion], [UsuarioModificacionID]) VALUES (16, '4e897005-40e2-40b8-8d57-b728ab490d2f', N'MPRO_VENTAS_POR_DIA', N'Ventas por Día', N'Ventas MPRO desglosadas por día', N'Ventas', N'CONSULTA', 2, N'SELECT      CONVERT(date, Vn_Fecha) as Fecha,     COUNT(DISTINCT Vn_Folio) as Tickets,     ISNULL(SUM(Vn_Importe), 0) as Venta FROM Venta WHERE Vn_Fecha >= ''{fecha_ini}''    AND Vn_Fecha <= ''{fecha_fin} 23:59:59''   AND ISNULL(Es_Cve_Estado, '''') <> ''CA'' GROUP BY CONVERT(date, Vn_Fecha) ORDER BY CONVERT(date, Vn_Fecha)', 1, 0, 0, 1, 1, 0, 1, 1, N'LEGACY_PYTHON', N'2026-05-15T04:08:18.046666', N'SISTEMA', NULL, NULL);
INSERT INTO [ConsultasSQL_Catalogo] ([ConsultaID], [PublicUUID], [CodigoConsulta], [NombreConsulta], [Descripcion], [Modulo], [TipoConsulta], [SistemaTipoID], [ConsultaSQL], [EsSistema], [EsPersonalizada], [EsSincronizable], [PermiteEjecucionManual], [SoloLectura], [RequiereAutorizacion], [Activo], [Version], [ConfigOrigen], [FechaCreacion], [UsuarioCreacionID], [FechaModificacion], [UsuarioModificacionID]) VALUES (17, 'fb176b77-e53d-4944-983b-178bf14dd94c', N'MPRO_VENTAS_POR_SUCURSAL', N'Ventas por Sucursal', N'Ventas MPRO por sucursal/almacén', N'Ventas', N'CONSULTA', 2, N'SELECT      ISNULL(A.Al_Descripcion, ''Sin sucursal'') as Sucursal,     COUNT(DISTINCT V.Vn_Folio) as Tickets,     ISNULL(SUM(V.Vn_Importe), 0) as Venta FROM Venta V LEFT JOIN Almacen A ON A.Al_Cve_Almacen = V.Al_Cve_Almacen WHERE V.Vn_Fecha >= ''{fecha_ini}''    AND V.Vn_Fecha <= ''{fecha_fin} 23:59:59''   AND ISNULL(V.Es_Cve_Estado, '''') <> ''CA'' GROUP BY A.Al_Descripcion ORDER BY SUM(V.Vn_Importe) DESC', 1, 0, 0, 1, 1, 0, 1, 1, N'LEGACY_PYTHON', N'2026-05-15T04:08:18.050000', N'SISTEMA', NULL, NULL);
INSERT INTO [ConsultasSQL_Catalogo] ([ConsultaID], [PublicUUID], [CodigoConsulta], [NombreConsulta], [Descripcion], [Modulo], [TipoConsulta], [SistemaTipoID], [ConsultaSQL], [EsSistema], [EsPersonalizada], [EsSincronizable], [PermiteEjecucionManual], [SoloLectura], [RequiereAutorizacion], [Activo], [Version], [ConfigOrigen], [FechaCreacion], [UsuarioCreacionID], [FechaModificacion], [UsuarioModificacionID]) VALUES (18, 'c7482397-55d9-4866-812b-979ff378fc19', N'MPRO_VENTAS_POR_PRODUCTO', N'Ventas por Producto', N'Top productos MPRO más vendidos', N'Ventas', N'CONSULTA', 2, N'SELECT TOP 50     P.Pd_Cve_Producto as Codigo,     P.Pd_Descripcion as Producto,     SUM(V.Vn_Cantidad_1) as Cantidad,     SUM(V.Vn_Importe) as Venta FROM Venta V INNER JOIN Producto P ON P.Pd_Cve_Producto = V.Pd_Cve_Producto WHERE V.Vn_Fecha >= ''{fecha_ini}''    AND V.Vn_Fecha <= ''{fecha_fin} 23:59:59''   AND ISNULL(V.Es_Cve_Estado, '''') <> ''CA'' GROUP BY P.Pd_Cve_Producto, P.Pd_Descripcion ORDER BY SUM(V.Vn_Importe) DESC', 1, 0, 0, 1, 1, 0, 1, 1, N'LEGACY_PYTHON', N'2026-05-15T04:08:18.050000', N'SISTEMA', NULL, NULL);
INSERT INTO [ConsultasSQL_Catalogo] ([ConsultaID], [PublicUUID], [CodigoConsulta], [NombreConsulta], [Descripcion], [Modulo], [TipoConsulta], [SistemaTipoID], [ConsultaSQL], [EsSistema], [EsPersonalizada], [EsSincronizable], [PermiteEjecucionManual], [SoloLectura], [RequiereAutorizacion], [Activo], [Version], [ConfigOrigen], [FechaCreacion], [UsuarioCreacionID], [FechaModificacion], [UsuarioModificacionID]) VALUES (19, '2d347d5e-26d8-4156-a089-1a38aff7ee8e', N'MPRO_COMPRAS_PERIODO', N'Compras por Período', N'Total de compras MPRO', N'Compras', N'CONSULTA', 2, N'SELECT      COUNT(DISTINCT RC.Rc_Folio) as Facturas,     ISNULL(SUM(RCD.Rd_Cantidad * RCD.Rd_Costo), 0) as Compra_Total FROM REQUISICION_COMPRA RC INNER JOIN REQUISICION_COMPRA_DETALLE RCD ON RCD.Rc_Folio = RC.Rc_Folio WHERE RC.Rc_FechaCaptura >= ''{fecha_ini}''    AND RC.Rc_FechaCaptura <= ''{fecha_fin} 23:59:59''', 1, 0, 0, 1, 1, 0, 1, 1, N'LEGACY_PYTHON', N'2026-05-15T04:08:18.050000', N'SISTEMA', NULL, NULL);
INSERT INTO [ConsultasSQL_Catalogo] ([ConsultaID], [PublicUUID], [CodigoConsulta], [NombreConsulta], [Descripcion], [Modulo], [TipoConsulta], [SistemaTipoID], [ConsultaSQL], [EsSistema], [EsPersonalizada], [EsSincronizable], [PermiteEjecucionManual], [SoloLectura], [RequiereAutorizacion], [Activo], [Version], [ConfigOrigen], [FechaCreacion], [UsuarioCreacionID], [FechaModificacion], [UsuarioModificacionID]) VALUES (20, 'e95a15a4-45d8-49cc-823b-fe948bec7bcb', N'MPRO_COMPRAS_POR_PROVEEDOR', N'Compras por Proveedor', N'Compras MPRO por proveedor', N'Compras', N'CONSULTA', 2, N'SELECT      ISNULL(P.Pv_Descripcion, ''Sin proveedor'') as Proveedor,     COUNT(DISTINCT RC.Rc_Folio) as Facturas,     ISNULL(SUM(RCD.Rd_Cantidad * RCD.Rd_Costo), 0) as Compra_Total FROM REQUISICION_COMPRA RC INNER JOIN REQUISICION_COMPRA_DETALLE RCD ON RCD.Rc_Folio = RC.Rc_Folio LEFT JOIN Proveedor P ON P.Pv_Cve_Proveedor = RC.Pv_Cve_Proveedor WHERE RC.Rc_FechaCaptura >= ''{fecha_ini}''    AND RC.Rc_FechaCaptura <= ''{fecha_fin} 23:59:59'' GROUP BY P.Pv_Descripcion ORDER BY SUM(RCD.Rd_Cantidad * RCD.Rd_Costo) DESC', 1, 0, 0, 1, 1, 0, 1, 1, N'LEGACY_PYTHON', N'2026-05-15T04:08:18.050000', N'SISTEMA', NULL, NULL);
